const novaData = $('Leer NOVA').first().json.values || [];
const dnspaceData = $('Leer DnSpace').first().json.values || [];

function cleanPhone(p) {
  if (!p) return '';
  let digits = String(p).replace(/\D/g, '');
  if (digits.length === 10 && ['3', '4', '7', '8', '9'].includes(digits[0])) {
    digits = '1' + digits;
  }
  return digits;
}

function cleanStr(s) {
  return String(s || '').trim().toLowerCase();
}

// 1. Index DnSpace records
const dnUsers = {};
const dnPhones = {};
const dnEmails = {};
const dnNames = {};

for (let idx = 1; idx < dnspaceData.length; idx++) {
  const r = dnspaceData[idx];
  if (!r || r.length === 0) continue;
  const rowNum = idx + 1;
  const nombre = r[0] || '';
  const apellido = r[1] || '';
  const tel = r[2] || '';
  const usuario = r[3] || '';
  const email = r[11] || '';
  const vence = r[5] || '';
  const play = r[12] || '';

  const fullName = `${cleanStr(nombre)} ${cleanStr(apellido)}`.trim();
  const cUser = cleanStr(usuario);
  const cPhone = cleanPhone(tel);
  const cEmail = cleanStr(email);

  const entry = { rowNum, nombre, apellido, fullName, usuario, cUser, tel, cPhone, email, cEmail, vence, play };

  if (cUser) dnUsers[cUser] = entry;
  if (cPhone) dnPhones[cPhone] = entry;
  if (cEmail && cEmail.includes('@')) dnEmails[cEmail] = entry;
  if (fullName) dnNames[fullName] = entry;
}

// 2. Cross-reference NOVA against DnSpace and clean phones from row 79
const matches = [];
const phoneCleanups = [];
const dataEntries = [];

for (let idx = 1; idx < novaData.length; idx++) {
  const r = novaData[idx];
  const rowNum = idx + 1;
  if (!r || r.length === 0) continue;

  const nombre = r[0] || '';
  const apellido = r[1] || '';
  const tel = r[2] || '';
  const usuario = r[3] || '';
  const email = r[11] || '';

  const fullName = `${cleanStr(nombre)} ${cleanStr(apellido)}`.trim();
  const cUser = cleanStr(usuario);
  const cPhone = cleanPhone(tel);
  const cEmail = cleanStr(email);

  let dnMatch = null;
  const matchReasons = [];

  if (cUser && dnUsers[cUser]) {
    matchReasons.push(`Usuario exacto (${usuario})`);
    dnMatch = dnUsers[cUser];
  }
  if (cPhone && dnPhones[cPhone]) {
    matchReasons.push(`Teléfono exacto (${cPhone})`);
    dnMatch = dnMatch || dnPhones[cPhone];
  }
  if (cEmail && cEmail.includes('@') && dnEmails[cEmail]) {
    matchReasons.push(`Email exacto (${email})`);
    dnMatch = dnMatch || dnEmails[cEmail];
  }
  if (!dnMatch && fullName && dnNames[fullName]) {
    matchReasons.push(`Nombre completo (${fullName})`);
    dnMatch = dnNames[fullName];
  }

  if (dnMatch) {
    matches.push({
      nova_row: rowNum,
      cliente: `${nombre} ${apellido}`.trim(),
      usuario: usuario,
      telefono: tel,
      email: email,
      dnspace_row: dnMatch.rowNum,
      dnspace_usuario: dnMatch.usuario,
      dnspace_vence: dnMatch.vence,
      reasons: matchReasons
    });

    dataEntries.push({
      range: `NOVA!N${rowNum}`,
      majorDimension: 'ROWS',
      values: [['ACTIVO']]
    });
  }

  // Check phone cleaning for row 79 onwards (rowNum >= 79)
  if (rowNum >= 79) {
    const hasDigits = /\d/.test(tel);
    if (hasDigits) {
      const cleanedPhone = tel.replace(/[\s\(\)\-\.\+]/g, '');
      if (cleanedPhone !== tel) {
        phoneCleanups.push({
          row: rowNum,
          cliente: `${nombre} ${apellido}`.trim(),
          original: tel,
          cleaned: cleanedPhone
        });

        dataEntries.push({
          range: `NOVA!C${rowNum}`,
          majorDimension: 'ROWS',
          values: [[cleanedPhone]]
        });
      }
    }
  }
}

const batchPayload = {
  valueInputOption: 'USER_ENTERED',
  data: dataEntries
};

return [{
  json: {
    total_matches: matches.length,
    matches: matches,
    total_phone_cleanups: phoneCleanups.length,
    phone_cleanups: phoneCleanups,
    total_updates_to_send: dataEntries.length,
    batch_payload: batchPayload
  }
}];

const processor = $('Procesar y Preparar BatchUpdate').first().json;
const apiResponse = $('Aplicar BatchUpdate Sheets').first().json;

return [{
  json: {
    status: 'success',
    spreadsheet_id: '1SNRbfgomUgtac58UmIMlH8UzizBXrTDVogxJEt-z9A0',
    sheet_name: 'NOVA',
    total_active_clients_marked: processor.total_matches,
    active_clients_list: processor.matches,
    total_phones_formatted: processor.total_phone_cleanups,
    formatted_phones_list: processor.phone_cleanups,
    total_ranges_updated: processor.total_updates_to_send,
    api_updated_cells: apiResponse.totalUpdatedCells || processor.total_updates_to_send,
    api_updated_rows: apiResponse.totalUpdatedRows || processor.total_updates_to_send,
    api_response: apiResponse
  }
}];
